css:
  :root {
    --paper: #f3efe4;
    --paper-raised: #faf7ee;
    --paper-deep: #e8e2d3;
    --ink: #12241c;
    --ink-soft: #44564b;
    --muted: #5f6c64;
    --line: #d8d1c1;
    --line-strong: #c0b8a6;
    --pine: #17372a;
    --pine-deep: #10271e;
    --ember: #d95d39;
    --ember-deep: #b94726;
    --sage: #78917b;
    --sage-light: #dfe6d9;
    --serif: "Iowan Old Style", "Palatino Linotype", "Book Antiqua", Palatino, Georgia, "Times New Roman", serif;
    --sans: -apple-system, BlinkMacSystemFont, "Segoe UI", "Helvetica Neue", Helvetica, Arial, sans-serif;
  }

  *, *::before, *::after { box-sizing: border-box; }
  html {
    scroll-behavior: smooth;
    -webkit-text-size-adjust: 100%;
  }
  body {
    margin: 0;
    overflow-x: hidden;
    overflow-x: clip;
    background: var(--paper);
    color: var(--ink);
    font-family: var(--sans);
    font-size: 16px;
    line-height: 1.5;
    -webkit-font-smoothing: antialiased;
    text-rendering: optimizeLegibility;
  }
  h1, h2, h3, p, ul, ol, figure { margin: 0; }
  ul, ol { padding: 0; list-style: none; }
  a { color: inherit; text-decoration: none; }
  svg { display: block; }
  ::selection { background: var(--ember); color: #fff8ed; }

  .wrap {
    width: min(calc(100% - 80px), 1240px);
    margin-inline: auto;
  }

  .eyebrow {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 22px;
    color: var(--ink-soft);
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.145em;
    line-height: 1.3;
    text-transform: uppercase;
  }
  .eyebrow::before {
    content: "";
    width: 20px;
    height: 1px;
    flex: none;
    background: var(--ember);
  }

  .btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    min-height: 52px;
    padding: 0 24px;
    border: 1px solid transparent;
    border-radius: 999px;
    font-family: var(--sans);
    font-size: 14px;
    font-weight: 650;
    letter-spacing: -0.01em;
    line-height: 1;
    white-space: nowrap;
    transition: background-color 180ms ease, border-color 180ms ease, color 180ms ease, transform 180ms ease;
  }
  .btn svg {
    width: 15px;
    height: 15px;
    flex: none;
    transition: transform 180ms ease;
  }
  .btn:hover svg { transform: translateX(3px); }
  .btn:active { transform: translateY(1px); }
  .btn-primary {
    background: var(--ink);
    color: var(--paper-raised);
  }
  .btn-primary:hover { background: var(--ember-deep); }
  .btn-secondary {
    border-color: var(--line-strong);
    color: var(--ink);
    background: transparent;
  }
  .btn-secondary:hover {
    border-color: var(--ink);
    background: rgba(18, 36, 28, 0.045);
  }
  .btn-small {
    min-height: 42px;
    padding: 0 18px;
    font-size: 12.5px;
  }

  /* Header */
  .site-header {
    position: relative;
    z-index: 20;
  }
  .nav-inner {
    display: flex;
    align-items: center;
    gap: 32px;
    padding-block: 26px;
  }
  .brand {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    min-height: 44px;
    font-size: 19px;
    font-weight: 700;
    letter-spacing: -0.035em;
  }
  .brand-mark {
    width: 31px;
    height: 31px;
    flex: none;
    border-radius: 9px;
  }
  .nav-links {
    display: flex;
    align-items: center;
    gap: 30px;
    margin-left: auto;
    color: var(--ink-soft);
    font-size: 13px;
    font-weight: 550;
  }
  .nav-links a {
    position: relative;
    display: inline-flex;
    align-items: center;
    min-height: 44px;
  }
  .nav-links a::after {
    content: "";
    position: absolute;
    left: 0;
    right: 100%;
    bottom: 10px;
    height: 1px;
    background: var(--ember-deep);
    transition: right 180ms ease;
  }
  .nav-links a:hover::after { right: 0; }

  /* Hero */
  .hero {
    position: relative;
    padding: 58px 0 104px;
  }
  .hero::before {
    content: "";
    position: absolute;
    top: -280px;
    right: -240px;
    width: 740px;
    height: 740px;
    border-radius: 50%;
    pointer-events: none;
    background: radial-gradient(circle, rgba(217, 93, 57, 0.11) 0%, rgba(217, 93, 57, 0) 67%);
  }
  .hero-grid {
    display: grid;
    grid-template-columns: minmax(0, 1.04fr) minmax(420px, 0.96fr);
    gap: 42px;
    align-items: center;
  }
  .hero-copy {
    position: relative;
    z-index: 2;
    padding: 12px 0 4px;
  }
  .hero h1 {
    font-family: var(--serif);
    font-size: clamp(3.5rem, 7.55vw, 6.95rem);
    font-weight: 400;
    letter-spacing: -0.047em;
    line-height: 0.92;
  }
  .hero h1 .line { display: block; }
  .hero h1 em {
    position: relative;
    display: inline-block;
    color: var(--ember-deep);
    font-style: italic;
    font-weight: 400;
    padding-right: 0.035em;
  }
  .h1-underline {
    position: absolute;
    left: 1%;
    bottom: -0.075em;
    width: 97%;
    height: 0.115em;
    overflow: visible;
    color: var(--ember);
  }
  .hero-sub {
    max-width: 530px;
    text-wrap: pretty;
    margin-top: 31px;
    color: var(--ink-soft);
    font-size: clamp(16.5px, 1.25vw, 19px);
    line-height: 1.62;
    letter-spacing: -0.012em;
  }
  .hero-actions {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 11px;
    margin-top: 34px;
  }
  .hero-meta {
    display: flex;
    align-items: center;
    gap: 9px;
    margin-top: 32px;
    color: var(--muted);
    font-size: 12px;
    letter-spacing: 0.01em;
  }
  .hero-meta::before {
    content: "";
    width: 5px;
    height: 5px;
    flex: none;
    border-radius: 50%;
    background: var(--sage);
    box-shadow: 0 0 0 4px var(--sage-light);
  }

  /* Hero product visual */
  .hero-visual {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: flex-end;
    min-height: 574px;
    z-index: 1;
  }
  .visual-stage {
    position: relative;
    width: 100%;
    max-width: 500px;
    padding: 38px 10px 38px 18px;
  }
  .visual-disc {
    position: absolute;
    top: 50%;
    right: -21px;
    width: 446px;
    height: 446px;
    border-radius: 50%;
    background: var(--sage-light);
    transform: translateY(-50%);
  }
  .visual-disc::before {
    content: "";
    position: absolute;
    inset: 21px;
    border: 1px solid rgba(18, 36, 28, 0.11);
    border-radius: inherit;
  }
  .visual-disc::after {
    content: "";
    position: absolute;
    top: 28px;
    right: 27px;
    width: 88px;
    height: 88px;
    border: 1px solid rgba(18, 36, 28, 0.13);
    border-radius: 50%;
  }
  .dot-field {
    position: absolute;
    top: 20px;
    left: 0;
    width: 114px;
    height: 76px;
    opacity: 0.62;
    background-image: radial-gradient(circle, rgba(18, 36, 28, 0.4) 1.15px, transparent 1.3px);
    background-size: 13px 13px;
  }
  .review-shell {
    position: relative;
    z-index: 2;
    width: 100%;
    transform: rotate(-1.15deg);
  }
  .review-back {
    position: absolute;
    z-index: 0;
    inset: 13px -10px -14px 16px;
    border-radius: 27px;
    background: var(--pine);
    box-shadow: 0 30px 70px rgba(16, 39, 30, 0.2);
    transform: rotate(2.7deg);
  }
  .review-panel {
    position: relative;
    z-index: 1;
    padding: 22px;
    border: 1px solid rgba(18, 36, 28, 0.13);
    border-radius: 23px;
    background: var(--paper-raised);
    box-shadow: 0 30px 60px -30px rgba(18, 36, 28, 0.34), 0 2px 8px rgba(18, 36, 28, 0.04);
  }
  .review-head {
    display: flex;
    align-items: center;
    gap: 10px;
    padding-bottom: 16px;
    border-bottom: 1px solid var(--line);
  }
  .review-mark {
    display: grid;
    place-items: center;
    width: 34px;
    height: 34px;
    flex: none;
    border-radius: 9px;
    background: var(--ink);
    color: var(--paper-raised);
  }
  .review-mark svg { width: 18px; height: 18px; }
  .review-head-copy { display: grid; gap: 1px; }
  .review-kicker {
    color: var(--muted);
    font-size: 8.5px;
    font-weight: 700;
    letter-spacing: 0.13em;
    line-height: 1.4;
    text-transform: uppercase;
  }
  .review-title {
    font-size: 14.5px;
    font-weight: 700;
    letter-spacing: -0.025em;
    line-height: 1.3;
  }
  .review-period {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    margin-left: auto;
    padding: 6px 9px;
    border: 1px solid var(--line);
    border-radius: 999px;
    color: var(--ink-soft);
    font-size: 9.5px;
    font-weight: 600;
    white-space: nowrap;
  }
  .review-period::before {
    content: "";
    width: 5px;
    height: 5px;
    border-radius: 50%;
    background: #5f7f65;
    box-shadow: 0 0 0 3px rgba(95, 127, 101, 0.13);
  }
  .tx-list { margin-top: 13px; }
  .tx-row {
    display: grid;
    grid-template-columns: 34px minmax(0, 1fr) auto 18px;
    align-items: center;
    gap: 10px;
    padding: 11px 0;
    border-bottom: 1px solid rgba(216, 209, 193, 0.76);
  }
  .tx-icon {
    display: grid;
    place-items: center;
    width: 34px;
    height: 34px;
    border-radius: 9px;
    color: var(--ink);
  }
  .tx-icon svg { width: 16px; height: 16px; }
  .tx-icon--sand { background: #e9dfca; }
  .tx-icon--clay { background: #efdcd2; }
  .tx-icon--sage { background: #dde6d9; }
  .tx-copy { display: grid; gap: 1px; min-width: 0; }
  .tx-name {
    overflow: hidden;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: -0.01em;
    line-height: 1.35;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  .tx-sub {
    overflow: hidden;
    color: var(--muted);
    font-size: 9.5px;
    line-height: 1.4;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  .tx-tag {
    padding: 4px 7px;
    border: 1px solid var(--line);
    border-radius: 999px;
    background: var(--paper);
    color: var(--ink-soft);
    font-size: 9px;
    font-weight: 600;
    white-space: nowrap;
  }
  .tx-check {
    display: grid;
    place-items: center;
    width: 18px;
    height: 18px;
    border-radius: 50%;
    background: var(--sage-light);
    color: #355c40;
  }
  .tx-check svg { width: 10px; height: 10px; }
  .duplicate {
    margin-top: 14px;
    padding: 11px 12px 12px;
    border: 1px solid #e4b6a2;
    border-radius: 13px;
    background: #f4e1d7;
  }
  .duplicate-head {
    display: flex;
    align-items: center;
    gap: 6px;
    color: var(--ember-deep);
    font-size: 9px;
    font-weight: 750;
    letter-spacing: 0.075em;
    text-transform: uppercase;
  }
  .duplicate-head svg { width: 13px; height: 13px; }
  .duplicate-review {
    margin-left: auto;
    padding: 3px 7px;
    border: 1px solid rgba(185, 71, 38, 0.2);
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.56);
    color: var(--ink-soft);
    font-size: 8.5px;
    font-weight: 650;
    letter-spacing: 0;
    text-transform: none;
  }
  .duplicate-rows {
    display: grid;
    gap: 4px;
    margin-top: 8px;
  }
  .duplicate-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    padding: 6px 8px;
    border-radius: 7px;
    background: rgba(255, 255, 255, 0.54);
    font-size: 10px;
    font-weight: 650;
  }
  .duplicate-row span:last-child {
    color: var(--muted);
    font-size: 9px;
    font-weight: 500;
  }
  .review-foot {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    margin-top: 15px;
  }
  .review-ready {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    color: var(--ink-soft);
    font-size: 9.5px;
    line-height: 1.3;
  }
  .review-ready svg { width: 13px; height: 13px; color: #43664c; }
  .export-pill {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    padding: 9px 11px;
    border-radius: 8px;
    background: var(--ink);
    color: var(--paper-raised);
    font-size: 10px;
    font-weight: 650;
    white-space: nowrap;
  }
  .export-pill svg { width: 11px; height: 11px; }
  .float-note {
    position: absolute;
    z-index: 3;
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 8px 12px 8px 8px;
    border: 1px solid rgba(18, 36, 28, 0.13);
    border-radius: 999px;
    background: rgba(250, 247, 238, 0.97);
    box-shadow: 0 13px 30px -12px rgba(18, 36, 28, 0.26);
    color: var(--ink);
    font-size: 10.5px;
    font-weight: 650;
    letter-spacing: -0.01em;
    white-space: nowrap;
    animation: drift 7s ease-in-out infinite;
  }
  .float-note .note-icon {
    display: grid;
    place-items: center;
    width: 23px;
    height: 23px;
    flex: none;
    border-radius: 50%;
    background: var(--ink);
    color: var(--paper-raised);
  }
  .float-note .note-icon svg { width: 11px; height: 11px; }
  .float-note--a { top: 42px; left: -4px; }
  .float-note--b { right: -8px; bottom: 90px; animation-delay: -3.2s; }
  @keyframes drift {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(-7px); }
  }

  /* Features */
  .features {
    position: relative;
    padding: 108px 0 116px;
    border-top: 1px solid var(--line);
  }
  .section-head {
    display: grid;
    grid-template-columns: minmax(0, 1.18fr) minmax(280px, 0.82fr);
    gap: 72px;
    align-items: end;
    margin-bottom: 62px;
  }
  .section-head h2 {
    max-width: 700px;
    text-wrap: balance;
    font-family: var(--serif);
    font-size: clamp(2.55rem, 4.5vw, 4.15rem);
    font-weight: 400;
    letter-spacing: -0.04em;
    line-height: 1.01;
  }
  .section-lede {
    max-width: 370px;
    padding-bottom: 7px;
    color: var(--ink-soft);
    font-size: 15px;
    letter-spacing: -0.005em;
    line-height: 1.7;
  }
  .feature-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    border-top: 1px solid var(--line-strong);
  }
  .feature {
    position: relative;
    padding: 29px 40px 10px 0;
    border-right: 1px solid var(--line);
  }
  .feature + .feature { padding-left: 40px; }
  .feature:last-child {
    padding-right: 0;
    border-right: 0;
  }
  .feature-top {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 40px;
  }
  .feature-icon {
    display: grid;
    place-items: center;
    width: 50px;
    height: 50px;
    border: 1px solid var(--line-strong);
    border-radius: 50%;
    color: var(--ink);
    transition: background-color 220ms ease, border-color 220ms ease, color 220ms ease, transform 220ms ease;
  }
  .feature-icon svg { width: 21px; height: 21px; }
  .feature-index {
    color: var(--muted);
    font-family: var(--serif);
    font-size: 12px;
    letter-spacing: 0.09em;
  }
  .feature h3 {
    margin-bottom: 13px;
    font-family: var(--serif);
    font-size: clamp(1.45rem, 1.9vw, 1.75rem);
    font-weight: 400;
    letter-spacing: -0.025em;
    line-height: 1.2;
  }
  .feature p {
    max-width: 330px;
    text-wrap: pretty;
    color: var(--ink-soft);
    font-size: 14.5px;
    line-height: 1.7;
  }
  .feature:hover .feature-icon {
    border-color: var(--ink);
    background: var(--ink);
    color: var(--paper-raised);
    transform: translateY(-3px) rotate(-4deg);
  }

  /* How it works */
  .how {
    position: relative;
    overflow: hidden;
    padding: 108px 0 116px;
    background: var(--pine);
    color: var(--paper);
  }
  .how::before {
    content: "";
    position: absolute;
    top: -380px;
    right: -200px;
    width: 800px;
    height: 800px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(217, 93, 57, 0.25) 0%, rgba(217, 93, 57, 0) 68%);
    pointer-events: none;
  }
  .how::after {
    content: "";
    position: absolute;
    left: -50px;
    bottom: -190px;
    width: 460px;
    height: 460px;
    border: 1px solid rgba(243, 239, 228, 0.09);
    border-radius: 50%;
    pointer-events: none;
  }
  .how .wrap {
    position: relative;
    z-index: 1;
  }
  .how .eyebrow { color: rgba(243, 239, 228, 0.7); }
  .how .eyebrow::before { background: var(--ember); }
  .how-head {
    display: grid;
    grid-template-columns: minmax(0, 1.15fr) minmax(280px, 0.85fr);
    gap: 64px;
    align-items: end;
    margin-bottom: 68px;
  }
  .how h2 {
    max-width: 620px;
    text-wrap: balance;
    font-family: var(--serif);
    font-size: clamp(2.55rem, 4.4vw, 4rem);
    font-weight: 400;
    letter-spacing: -0.04em;
    line-height: 1.02;
  }
  .how-lede {
    max-width: 345px;
    padding-bottom: 7px;
    color: rgba(243, 239, 228, 0.7);
    font-size: 15px;
    line-height: 1.7;
  }
  .steps {
    position: relative;
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .steps::before {
    content: "";
    position: absolute;
    top: 27px;
    left: 28px;
    right: calc(33.333% - 68px);
    height: 1px;
    background: repeating-linear-gradient(90deg, rgba(243, 239, 228, 0.26) 0 4px, transparent 4px 11px);
  }
  .step {
    position: relative;
    padding-right: 40px;
  }
  .step + .step { padding-left: 40px; }
  .step-num {
    position: relative;
    z-index: 1;
    display: grid;
    place-items: center;
    width: 56px;
    height: 56px;
    border: 1px solid rgba(243, 239, 228, 0.24);
    border-radius: 50%;
    background: var(--pine);
    color: var(--paper);
    font-family: var(--serif);
    font-size: 15px;
    letter-spacing: 0.04em;
    transition: background-color 220ms ease, border-color 220ms ease;
  }
  .step h3 {
    margin-top: 28px;
    font-size: 19px;
    font-weight: 650;
    letter-spacing: -0.025em;
    line-height: 1.3;
  }
  .step p {
    max-width: 285px;
    margin-top: 11px;
    color: rgba(243, 239, 228, 0.64);
    font-size: 14px;
    line-height: 1.68;
  }
  .step:hover .step-num {
    border-color: var(--ember);
    background: var(--ember);
    color: #fff8ed;
  }

  /* Closing call to action */
  .closing {
    position: relative;
    overflow: hidden;
    padding-top: 92px;
    background: var(--ember-deep);
    color: var(--paper-raised);
  }
  .closing::before {
    content: "";
    position: absolute;
    top: -370px;
    right: -150px;
    width: 750px;
    height: 750px;
    border: 1px solid rgba(250, 247, 238, 0.17);
    border-radius: 50%;
    pointer-events: none;
  }
  .closing::after {
    content: "";
    position: absolute;
    top: -277px;
    right: -57px;
    width: 564px;
    height: 564px;
    border: 1px solid rgba(250, 247, 238, 0.11);
    border-radius: 50%;
    pointer-events: none;
  }
  .closing-inner {
    position: relative;
    z-index: 1;
    display: grid;
    grid-template-columns: minmax(0, 1fr) 230px;
    gap: 56px;
    align-items: end;
    padding-bottom: 92px;
  }
  .closing .eyebrow { color: var(--paper-raised); }
  .closing .eyebrow::before { background: var(--paper-raised); }
  .closing h2 {
    max-width: 850px;
    text-wrap: balance;
    font-family: var(--serif);
    font-size: clamp(3rem, 6.25vw, 6.2rem);
    font-weight: 400;
    letter-spacing: -0.048em;
    line-height: 0.98;
  }
  .closing h2 em { font-style: italic; font-weight: 400; }
  .closing-actions {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 11px;
    margin-top: 38px;
  }
  .btn-cream {
    background: var(--paper-raised);
    color: var(--ink);
  }
  .btn-cream:hover { background: #fffdf7; }
